-- NewsVista schema (PostgreSQL / Supabase). Generated by scripts/dump_schema.py.
-- The API also runs metadata.create_all() at startup, which is idempotent.

CREATE TABLE IF NOT EXISTS ai_call_log (
	id SERIAL NOT NULL, 
	called_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	run_id INTEGER, 
	story_id VARCHAR(32) NOT NULL, 
	model VARCHAR(100) NOT NULL, 
	outcome VARCHAR(32) NOT NULL, 
	latency_ms INTEGER NOT NULL, 
	error TEXT, 
	PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS ix_ai_call_log_called_at ON ai_call_log (called_at);

CREATE TABLE IF NOT EXISTS background_links (
	id SERIAL NOT NULL, 
	url TEXT NOT NULL, 
	title TEXT NOT NULL, 
	description TEXT NOT NULL, 
	provider VARCHAR(64) NOT NULL, 
	fetched_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (url)
);


CREATE TABLE IF NOT EXISTS collection_runs (
	id SERIAL NOT NULL, 
	trigger VARCHAR(32) NOT NULL, 
	started_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	finished_at TIMESTAMP WITH TIME ZONE, 
	status VARCHAR(16) NOT NULL, 
	articles_fetched INTEGER NOT NULL, 
	articles_new INTEGER NOT NULL, 
	articles_updated INTEGER NOT NULL, 
	articles_unchanged INTEGER NOT NULL, 
	skipped_invalid_date INTEGER NOT NULL, 
	skipped_future INTEGER NOT NULL, 
	skipped_too_old INTEGER NOT NULL, 
	articles_expired INTEGER NOT NULL, 
	stories_created INTEGER NOT NULL, 
	stories_joined INTEGER NOT NULL, 
	stories_deleted INTEGER NOT NULL, 
	analyses_invalidated INTEGER NOT NULL, 
	ai_generated INTEGER NOT NULL, 
	ai_failed INTEGER NOT NULL, 
	ai_deferred INTEGER NOT NULL, 
	background_links_added INTEGER NOT NULL, 
	error TEXT, 
	PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS ix_collection_runs_started_at ON collection_runs (started_at);

CREATE TABLE IF NOT EXISTS sources (
	id VARCHAR(64) NOT NULL, 
	publisher VARCHAR(100) NOT NULL, 
	name VARCHAR(120) NOT NULL, 
	feed_url TEXT NOT NULL, 
	homepage TEXT, 
	active BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id)
);


CREATE TABLE IF NOT EXISTS stories (
	id VARCHAR(32) NOT NULL, 
	headline TEXT NOT NULL, 
	headline_article_id VARCHAR(32), 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	latest_published_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	background_checked_fp VARCHAR(64), 
	background_checked_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id)
);

CREATE INDEX IF NOT EXISTS ix_stories_latest_published_at ON stories (latest_published_at);

CREATE TABLE IF NOT EXISTS ai_analyses (
	id SERIAL NOT NULL, 
	story_id VARCHAR(32) NOT NULL, 
	status VARCHAR(24) NOT NULL, 
	fingerprint VARCHAR(64), 
	input_article_ids TEXT NOT NULL, 
	input_scope VARCHAR(32), 
	model VARCHAR(100), 
	prompt_version VARCHAR(32), 
	generated_at TIMESTAMP WITH TIME ZONE, 
	content_json TEXT, 
	needs_review BOOLEAN NOT NULL, 
	review_notes TEXT NOT NULL, 
	error TEXT, 
	version INTEGER NOT NULL, 
	last_attempt_at TIMESTAMP WITH TIME ZONE, 
	last_attempt_fp VARCHAR(64), 
	PRIMARY KEY (id), 
	UNIQUE (story_id), 
	FOREIGN KEY(story_id) REFERENCES stories (id) ON DELETE CASCADE
);


CREATE TABLE IF NOT EXISTS articles (
	id VARCHAR(32) NOT NULL, 
	source_id VARCHAR(64) NOT NULL, 
	publisher VARCHAR(100) NOT NULL, 
	title TEXT NOT NULL, 
	url TEXT NOT NULL, 
	normalized_url TEXT NOT NULL, 
	guid TEXT, 
	published_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	excerpt TEXT NOT NULL, 
	feed_text TEXT NOT NULL, 
	content_kind VARCHAR(32) NOT NULL, 
	content_hash VARCHAR(64) NOT NULL, 
	ingested_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	last_seen_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(source_id) REFERENCES sources (id), 
	UNIQUE (normalized_url)
);

CREATE INDEX IF NOT EXISTS ix_articles_publisher ON articles (publisher);
CREATE INDEX IF NOT EXISTS ix_articles_published_at ON articles (published_at);

CREATE TABLE IF NOT EXISTS collection_run_sources (
	id SERIAL NOT NULL, 
	run_id INTEGER NOT NULL, 
	source_id VARCHAR(64) NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	http_status INTEGER, 
	items_in_feed INTEGER NOT NULL, 
	"new" INTEGER NOT NULL, 
	updated INTEGER NOT NULL, 
	skipped INTEGER NOT NULL, 
	duration_ms INTEGER NOT NULL, 
	error TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(run_id) REFERENCES collection_runs (id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_run_sources_run ON collection_run_sources (run_id);

CREATE TABLE IF NOT EXISTS story_background (
	story_id VARCHAR(32) NOT NULL, 
	background_id INTEGER NOT NULL, 
	matched_term TEXT NOT NULL, 
	method VARCHAR(32) NOT NULL, 
	rank INTEGER NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (story_id, background_id), 
	FOREIGN KEY(story_id) REFERENCES stories (id) ON DELETE CASCADE, 
	FOREIGN KEY(background_id) REFERENCES background_links (id) ON DELETE CASCADE
);


CREATE TABLE IF NOT EXISTS story_articles (
	id SERIAL NOT NULL, 
	story_id VARCHAR(32) NOT NULL, 
	article_id VARCHAR(32) NOT NULL, 
	added_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	match_score DOUBLE PRECISION, 
	matched_article_id VARCHAR(32), 
	PRIMARY KEY (id), 
	CONSTRAINT uq_story_articles_article UNIQUE (article_id), 
	FOREIGN KEY(story_id) REFERENCES stories (id) ON DELETE CASCADE, 
	FOREIGN KEY(article_id) REFERENCES articles (id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS ix_story_articles_story_id ON story_articles (story_id);
